-extern "C" void run(const void* input1,const void* input2,void* output,int n,int parameter,int threads)
-{const int*a=(const int*)input1;int j=0;for(int i=1;i<n;i++)if(a[i]<a[j])j=i;*(int*)output=j;}
+#include <immintrin.h>
+
+extern "C" __attribute__((target("avx512f")))
+void run(const void* input1, const void*, void* output, int n, int, int)
+{
+    const int* a = static_cast<const int*>(input1);
+    int* result = static_cast<int*>(output);
+
+    if (n <= 0) {
+        *result = 0;
+        return;
+    }
+
+    if (n < 16) {
+        int best = 0;
+        for (int i = 1; i < n; ++i) {
+            if (a[i] < a[best]) {
+                best = i;
+            }
+        }
+        *result = best;
+        return;
+    }
+
+    // Seed from real input so INT32_MAX is a valid lane minimum.
+    __m512i lane_min = _mm512_loadu_si512(static_cast<const void*>(a));
+    int lane_index[16];
+    for (int lane = 0; lane < 16; ++lane) {
+        lane_index[lane] = lane;
+    }
+
+    int i = 16;
+    for (; i <= n - 16; i += 16) {
+        const __m512i values = _mm512_loadu_si512(static_cast<const void*>(a + i));
+        const __mmask16 changed = _mm512_cmp_epi32_mask(values, lane_min, _MM_CMPINT_LT);
+        lane_min = _mm512_mask_mov_epi32(lane_min, changed, values);
+
+        // Only lanes with a strictly smaller value need a new absolute index.
+        unsigned int pending = static_cast<unsigned int>(changed);
+        while (pending != 0) {
+            const unsigned int lane = static_cast<unsigned int>(__builtin_ctz(pending));
+            lane_index[lane] = i + static_cast<int>(lane);
+            pending &= pending - 1;
+        }
+    }
+
+    int lane_values[16];
+    _mm512_storeu_si512(static_cast<void*>(lane_values), lane_min);
+    int best_index = lane_index[0];
+    int best_value = lane_values[0];
+    for (int lane = 1; lane < 16; ++lane) {
+        if (lane_values[lane] < best_value ||
+            (lane_values[lane] == best_value && lane_index[lane] < best_index)) {
+            best_value = lane_values[lane];
+            best_index = lane_index[lane];
+        }
+    }
+
+    for (; i < n; ++i) {
+        if (a[i] < best_value || (a[i] == best_value && i < best_index)) {
+            best_value = a[i];
+            best_index = i;
+        }
+    }
+
+    *result = best_index;
+}"}], "interactions": [], "automatic_observations": {"baseline": {"experiment_id": "baseline-e1", "outcome": {"binary_sha256": "ab32d82af4b8f30380f36379054d8256875599a46aa666b645e25e1dfc119a8f", "cache_key": "f0faf02e8fe0dae7d87164f85e44b856523b5ebbd63cbde9d300ac2cfca5736e", "commit": "8c144b3264c47b324ac3723e891093bfdb9cd5f1", "correct": true, "logs": ["/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/logs/e1/baseline-e1/search/attempt-001/build.log", "/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/logs/e1/baseline-e1/search/attempt-001/correctness.log", "/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/logs/e1/baseline-e1/search/attempt-001/sample-0.log", "/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/logs/e1/baseline-e1/search/attempt-001/sample-1.log", "/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/logs/e1/baseline-e1/search/attempt-001/sample-2.log"], "mean_seconds": 4.4632395550290205e-06, "reason": "", "score": 0.5, "status": "valid", "times": [4.465990191647076e-06, 4.461839484554596e-06, 4.461888988885388e-06], "tree_hash": "a30dcb0c78318e4c5e657ea82feb01c07bc27de8"}, "raw_logs": [{"path": "logs/e1/baseline-e1/search/attempt-001/correctness.log", "truncated": false, "runner_output": {"correct": true, "cases": 5, "details": [{"case_id": "argmin", "binary": "/gpfs/scratch/nimarano/forest-active-argmin-571ae8eb9fca4076a77bea27e266397c/results-782994/reference-argmin/builds/e1/baseline-e1/search/attempt-001/solution", "n": 8192, "seed": 23, "pattern": 0, "threads": 1, "affinity": [170], "correct": true, "errors": 0, "input_unchanged": true, "guards": true, "max_abs_error": 0.0, "input_sha256": "63e8e07ea7cd665e913ddfc20524114b4353cb7c19200dbe8f90cf4d977a1dd8